export function canonicalIP(value){if(typeof value!=='string')throw Error('Use a numeric address.');if(value.includes(':')){const scoped=value.split('%');if(scoped.length>2||scoped.length===2&&!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,31}$/.test(scoped[1]))throw Error('Use one explicit interface name after %.');const zone=scoped[1]||'';value=scoped[0];if(!/^[a-fA-F0-9:]+$/.test(value)||value.includes(':::')||value.split('::').length>2)throw Error('Use an unscoped numeric IPv6 address.');let parts;if(value.includes('::')){const [a,b]=value.split('::').map(s=>s?s.split(':'):[]);if(a.length+b.length>=8)throw Error('Invalid IPv6 compression.');parts=[...a,...Array(8-a.length-b.length).fill('0'),...b];}else parts=value.split(':');if(parts.length!==8||parts.some(s=>!/^[a-fA-F0-9]{1,4}$/.test(s)))throw Error('Invalid IPv6 address.');const n=parts.map(s=>parseInt(s,16));if(n.every(x=>x===0)||(n[0]&0xff00)===0xff00||n.slice(0,5).every(x=>x===0)&&n[5]===0xffff)throw Error('Unspecified, multicast and mapped IPv6 are excluded.');const linkLocal=(n[0]&0xffc0)===0xfe80;if(linkLocal!==!!zone)throw Error('Link-local IPv6 requires an interface suffix; global addresses must not have one.');return n.map(x=>x.toString(16)).join(':')+(zone?'%'+zone:'');}if(!/^(0|[1-9]\d{0,2})(\.(0|[1-9]\d{0,2})){3}$/.test(value)||value.split('.').some(n=>+n>255)||+value.split('.')[0]===0||+value.split('.')[0]>=224)throw Error('Use a supported canonical numeric IPv4 address.');return value;}
export function destinationSet(targets){const result=targets.map(canonicalIP);if(new Set(result).size!==result.length||new Set(result.map(s=>s.includes(':'))).size!==1)throw Error('Use unique destinations of one address family.');return result;}
export function validateSavedProfiles(p){p.scanProfiles??=[];if(!Array.isArray(p.scanProfiles)||p.scanProfiles.length>100)throw Error('Invalid saved scan profiles.');const ids=new Set();for(const x of p.scanProfiles){if(!x||typeof x.id!=='string'||ids.has(x.id)||!p.devices.some(d=>d.id===x.deviceId)||typeof x.name!=='string'||!x.name.trim()||x.name.length>160||!x.input||Object.keys(x.input).some(k=>!['targets','ports','rate','timeout','serviceDetection','vantage','mode'].includes(k)))throw Error('Invalid saved scan profile.');if(x.input.mode!==undefined&&!['tcp','udp','discovery'].includes(x.input.mode))throw Error('Invalid saved scan mode.');ids.add(x.id);for(const k of ['targets','ports','vantage'])if(typeof x.input[k]!=='string'||x.input[k].length>2048)throw Error('Invalid saved scan field.');if(!Number.isInteger(x.input.rate)||x.input.rate<1||x.input.rate>100||!Number.isInteger(x.input.timeout)||x.input.timeout<10||x.input.timeout>300||typeof x.input.serviceDetection!=='boolean')throw Error('Invalid saved scan limits.');}return p;}
